#!/usr/bin/env node
// Row Level Security proof, generated by vibeproof Fix Pack.
// It creates two throwaway users, writes one row for each, and then checks
// what an anonymous visitor and the wrong logged-in user can actually reach.
//
//   npm i @supabase/supabase-js
//   SUPABASE_URL=... SUPABASE_ANON_KEY=... SUPABASE_SERVICE_ROLE_KEY=... node rls_tests.mjs
//
// Run it against a development or branch database, never production:
// it inserts and deletes rows.

import { createClient } from '@supabase/supabase-js';

const URL = process.env.SUPABASE_URL;
const ANON = process.env.SUPABASE_ANON_KEY;
const SERVICE = process.env.SUPABASE_SERVICE_ROLE_KEY;
if (!URL || !ANON || !SERVICE) {
  console.error('Set SUPABASE_URL, SUPABASE_ANON_KEY and SUPABASE_SERVICE_ROLE_KEY first.');
  process.exit(2);
}

