const admin = createClient(URL, SERVICE, { auth: { persistSession: false } });
const anon  = createClient(URL, ANON,    { auth: { persistSession: false } });

let pass = 0, fail = 0;
const failures = [];
function check(name, ok, detail) {
  if (ok) { pass++; console.log('  PASS  ' + name); }
  else { fail++; failures.push(name + (detail ? ' :: ' + detail : '')); console.log('  FAIL  ' + name + (detail ? '  -> ' + detail : '')); }
}

const stamp = Date.now();
const creds = [
  { email: `vibeproof.a.${stamp}@example.com`, password: 'Vp-' + stamp + '-aaaa' },
  { email: `vibeproof.b.${stamp}@example.com`, password: 'Vp-' + stamp + '-bbbb' },
];

async function makeUsers() {
  const users = [];
  for (const c of creds) {
    const { data, error } = await admin.auth.admin.createUser({ email: c.email, password: c.password, email_confirm: true });
    if (error) throw new Error('could not create a test user: ' + error.message);
    const client = createClient(URL, ANON, { auth: { persistSession: false } });
    const { error: signInError } = await client.auth.signInWithPassword({ email: c.email, password: c.password });
    if (signInError) throw new Error('could not sign in a test user: ' + signInError.message);
    users.push({ id: data.user.id, client });
  }
  return users;
}

function sampleValue(col) {
  const t = (col.type || '').toLowerCase();
  if (t.includes('uuid')) return crypto.randomUUID();
  if (t.includes('int') || t.includes('numeric') || t.includes('decimal') || t.includes('real') || t.includes('double')) return 1;
  if (t.includes('bool')) return false;
  if (t.includes('timestamp') || t.includes('date')) return new Date().toISOString();
  if (t.includes('json')) return {};
  return 'vibeproof-test';
}

function seedRow(t, userId) {
  const row = {};
  for (const c of t.columns) {
    if (c.name === t.column) { row[c.name] = userId; continue; }
    if (c.name === 'id' && (c.type || '').includes('uuid')) { row[c.name] = crypto.randomUUID(); continue; }
    if (c.notNull) row[c.name] = sampleValue(c);
  }
  if (t.kind === 'self') row[t.column] = userId;
  return row;
}

const cleanup = [];

async function run() {
  console.log('\nvibeproof :: Row Level Security proof\n');
  const [a, b] = await makeUsers();
  console.log('  two test users created\n');

  for (const t of TABLES) {
    console.log('  table: ' + t.table);
    const row = seedRow(t, a.id);
    const { data: inserted, error: seedErr } = await admin.from(t.table).insert(row).select().maybeSingle();
    if (seedErr) {
      console.log('  SKIP  ' + t.table + ' -> could not seed a row (' + seedErr.message + ')');
      console.log('');
      continue;
    }
    const rowId = inserted && inserted.id;
    if (rowId) cleanup.push({ table: t.table, id: rowId });

    // 1. An anonymous visitor must not be able to read the row.
    {
      const { data, error } = await anon.from(t.table).select('*').limit(50);
      const leaked = !error && Array.isArray(data) && data.length > 0;
      check(t.table + ': anonymous read is blocked', !leaked,
        leaked ? `anon read back ${data.length} row(s)` : '');
    }
    // 2. An anonymous visitor must not be able to insert.
    {
      const { error } = await anon.from(t.table).insert(seedRow(t, a.id));
      check(t.table + ': anonymous insert is blocked', !!error, error ? '' : 'insert succeeded');
    }
    // 3. A different logged-in user must not see the row.
    {
      const { data, error } = await b.client.from(t.table).select('*').limit(50);
      const sawOthers = !error && Array.isArray(data) && data.some(r => rowId ? r.id === rowId : false);
      check(t.table + ": another user cannot read this user's rows", !sawOthers,
        sawOthers ? 'user B read user A row' : '');
    }
    // 4. A different logged-in user must not be able to change or delete the row.
    if (rowId) {
      const { data: upd } = await b.client.from(t.table).update({ [t.columns.find(c => c.name !== 'id' && c.name !== t.column && !(c.type||'').includes('uuid'))?.name || t.column]: 'hacked' }).eq('id', rowId).select();
      check(t.table + ": another user cannot modify this user's row", !upd || upd.length === 0,
        (upd && upd.length) ? 'update affected ' + upd.length + ' row(s)' : '');
      const { data: del } = await b.client.from(t.table).delete().eq('id', rowId).select();
      check(t.table + ": another user cannot delete this user's row", !del || del.length === 0,
        (del && del.length) ? 'delete removed ' + del.length + ' row(s)' : '');
    }
    // 5. The owner must still be able to read their own row.
    {
      const { data, error } = await a.client.from(t.table).select('*').limit(50);
      const ownerCanRead = !error && Array.isArray(data) && (rowId ? data.some(r => r.id === rowId) : data.length >= 0);
      check(t.table + ': the owner can still read their own row', ownerCanRead,
        error ? error.message : 'owner saw nothing - the policy may be too strict');
    }
    console.log('');
  }
}

async function tearDown() {
  for (const c of cleanup) { try { await admin.from(c.table).delete().eq('id', c.id); } catch {} }
  for (const c of creds) {
    try {
      const { data } = await admin.auth.admin.listUsers();
      const u = data && data.users && data.users.find(u => u.email === c.email);
      if (u) await admin.auth.admin.deleteUser(u.id);
    } catch {}
  }
}

run()
  .then(tearDown)
  .then(() => {
    console.log(`\n  ${pass} passed, ${fail} failed`);
    if (fail) {
      console.log('\n  Still reachable:');
      for (const f of failures) console.log('    - ' + f);
      console.log('\n  Apply rls_policies.sql, then run this again.');
    } else {
      console.log('\n  Every table above denied the anonymous visitor and the wrong user.');
    }
    process.exit(fail ? 1 : 0);
  })
  .catch(async (e) => { await tearDown(); console.error('\n  Error: ' + e.message); process.exit(2); });
